def median(xs: list[float]) -> float:
    """Median of a non-empty list. For even length, the mean of the two middle values."""
    sorted_xs = sorted(xs)
    n = len(sorted_xs)
    mid = n // 2

    if n % 2 == 1:
        return sorted_xs[mid]
    else:
        return (sorted_xs[mid - 1] + sorted_xs[mid]) / 2

def roman(n: int) -> str:
    val = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    res = []
    for num, sym in val:
        while n >= num:
            res.append(sym)
            n -= num
    return ''.join(res)

