def merge_intervals(xs: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not xs:
        return []

    # Sort intervals based on the start value
    sorted_intervals = sorted(xs, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current in sorted_intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping or touching intervals, merge them
            new_start = last[0]
            new_end = max(last[1], current[1])
            merged[-1] = (new_start, new_end)
        else:
            merged.append(current)

    return merged

def word_count(s: str) -> dict[str, int]:
    """Count lowercase words split on whitespace."""
    words = s.lower().split()
    count = {}
    for word in words:
        count[word] = count.get(word, 0) + 1
    return count

